head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.coBzProcsNo = "";             // 회사 업무처리번호 — 비면 종목을 등록할 수 없다 (AS-IS parentWin.scwin.vBzProcsNo)
scwin.bzProcsNo = "";               // 이 종목 건의 업무처리번호 — 비면 신규 (AS-IS parentWin.scwin.clickBzProcsNo)
scwin.secugrpId = "";               // 증권그룹ID (AS-IS vSecugrpID)
scwin.prelmInvstgBzProcsNo = "";    // 예비심사 업무처리번호 — 종류주식상세(05106)에 넘긴다 (AS-IS vPRELM_INVSTG_BZ_PROCS_NO)
scwin.mktTpCd = "";                 // 시장구분 1: 유가, 2: 코스닥 (AS-IS vSPOT_ISU_TRD_MKT_TP_CD)
scwin.comAbbrv = "";                // 회사 한글약명 — 보통주 약명 일치 검사용 (AS-IS parentWin.txb_COM_ABBRV)
scwin.trJob = "";                   // 처리구분 I: 저장, U: 수정, D: 삭제 (AS-IS TR_JOB)
scwin.isSaved = false;              // 저장·수정·삭제에 한 번이라도 성공했는가 — 닫을 때 부모에 돌려준다
scwin.isuShrsLabelNm = "주식";      // 검증 문구의 주식/DR 표기 (AS-IS visuShrsLabelNm)
scwin.STKCERT_KIND_CD_COMMON = "000";                           // 주식의종류 — 보통주
// 원본 : ULDSTF05113.xml (W-Craft 1차 변환본에 API 적용까지 마친 개발 사본, meta_asisFileNm ULDSTF05113.gfm — 원본 gfm 은 저장소에 없음)
/*
 * 화면 동작
 *  - 부모(종류주식 신규상장관리 ULDSTF05103·05104)가 회사·종목 키를 data 로 넘겨 연다. 업무처리번호(bzProcsNo)가 없으면 신규, 있으면 수정이다.
 *  - 신규: 회사 업무처리번호(coBzProcsNo)가 없으면 "먼저 회사정보를 입력" 을 안내하고 처리 버튼을 잠근다.
 *    상장일·상장방식(신규상장)·유가 영문심볼 기본값을 채우고, [종목 찾기]로 미상장 종목을 고르면
 *    종목 정보·주식의종류·신형우선주 존속기한·변경전 상장주식수/자본금을 채운다.
 *  - 증감주식수·액면가·발행사유를 바꾸면 증감 상장자본금·변경후 상장주식수/자본금을 다시 계산한다(무액면이면 자본금은 손입력).
 *  - 보통주(000)는 한글종목약명이 회사 약명(부모가 넘긴 comAbbrv)과 같아야 저장할 수 있다.
 *  - 저장·수정·삭제에 성공하면 scwin.isSaved 를 세운다. 삭제는 팝업을 닫으며 { isSaved : true } 를 돌려주고,
 *    부모는 isSaved 이거나 X 로 닫혔으면 목록을 다시 조회한다(공통 계약서 §2 부모 재조회 규약).
 *  - 통신은 화면에 적용된 API(경로·method·keyInfo)를 명세로 본다(사용자 결정 2026-10-29).
 *    신형우선주 이력만은 이 화면에 API 가 적용되지 않아 같은 업무의 ULDSTF05105 에 적용된 API 를 쓴다(§10 #3).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05113/ULDSTF05113.md (§번호는 이 문서의 절)
 */

// 부모 화면에서 넘겨받는 값 (§1.2)

// 화면 상태값

// 고정값
scwin.JOB_NM = { I : "저장", U : "수정", D : "삭제" };
scwin.LIST_PROCS_STAT_CD = { I : "20", U : "", D : "50" };      // 처리구분별 상장처리상태코드 (AS-IS fn_trs)
// 자본금이 늘지 않는 주식발행사유 — 유가 118 이익소각·160 상호변경·170 액면병합·171 액면분할 / 코스닥 626·643·640·641
scwin.NO_CAP_RSN_CD = ["118", "160", "170", "171", "626", "643", "640", "641"];

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete"     // [삭제]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05113.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로딩 — 버튼 잠금 → 파라미터 수신 → 공통 코드(통화·발행사유) → 증권그룹·시장별 화면 → 달력 바인딩 → 모드 분기(수정 조회 / 신규 준비). (원본 init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금 — 조회가 예외로 끝나도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
    $c.util.setButtonState("grp_btnBox", "disabled", scwin.BTN_MAP);

    // 2) 파라미터 수신 — 원본은 $c.win.getParent() 로 부모 컴포넌트를 직접 읽었다 (§1.2, 공통 계약서 §2)
    const param = $c.data.getParameter() ?? {};
    scwin.coBzProcsNo = String(param.coBzProcsNo ?? "");
    scwin.bzProcsNo = String(param.bzProcsNo ?? "");
    scwin.secugrpId = String(param.secugrpId ?? "");
    scwin.prelmInvstgBzProcsNo = String(param.prelmInvstgBzProcsNo ?? "");
    scwin.mktTpCd = String(param.spotIsuTrdMktTpCd ?? "");
    scwin.comAbbrv = String(param.comAbbrv ?? "");
    txb_COM_NM.setValue(String(param.comNm ?? ""));

    // 3) 공통 코드(통화·주식발행사유) · 무액면 기본값 (원본 fn_searchCode · fn_SetComboCode)
    await scwin.selectCode();
    scwin.initNparval();

    // 4) 증권그룹(DR·FS)별 라벨·자본금 영역, 시장별 영문심볼 입력 (원본 fn_setInitLabel · fn_setSumblComponent)
    scwin.setInitLabel();
    scwin.setSymblComponent();

    // 5) 달력 검사 바인딩(1회) — 단일 달력은 checkCalendarFormat (규칙 37)
    $c.date.checkCalendarFormat(edt_LIST_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_ISU_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_PREFSTK_END_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_DIV_RECK_DD1, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_DIV_RECK_DD2, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_DIV_RECK_DD3, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_DIV_RECK_DD4, "yyyyMMdd");

    // 6) 모드 분기
    if (scwin.bzProcsNo !== "") {
        await scwin.selectDetail();
    } else {
        await scwin.initNewForm(param);
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.img_ISU_CD_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 찾기(돋보기) 버튼 클릭 — 발행기관의 미상장종목 찾기 (원본 img_ISU_CD onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_ISU_CD_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05113.img_ISU_CD_onclick" });
    }
};

