/**
 * @method
 * @name scwin.edt_PARVAL_onblur
 * @author Inswave
 * @date 2026. 10. 29
 * @description 액면가 입력을 마치면 증감·변경후 상장자본금을 다시 계산한다 — 무액면이면 계산하지 않는다 (원본 edt_PARVAL OnKillFocus — §6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.edt_PARVAL_onblur = function (e) {
    try {
        if (!scwin.isNparval()) {
            scwin.calcIsuCap();
            scwin.calcAccIsuCap();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05113.edt_PARVAL_onblur" });
    }
};

/**
 * @method
 * @name scwin.cmb_STK_ISU_RSN_CD_onviewchange
 * @author Inswave
 * @date 2026. 10. 29
 * @description 주식발행사유 변경 — 변경후 상장주식수와(무액면이 아니면) 상장자본금을 다시 계산한다 (원본 cmb_STK_ISU_RSN_CD OnSelChange — §6.3)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.cmb_STK_ISU_RSN_CD_onviewchange = function (info) {
    try {
        scwin.calcAccIsuShrs();
        if (!scwin.isNparval()) {
            scwin.calcAccIsuCap();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05113.cmb_STK_ISU_RSN_CD_onviewchange" });
    }
};

