/**
 * @method
 * @name scwin.cmb_NPARVALSTK_YN_onviewchange
 * @author Inswave
 * @date 2026. 10. 29
 * @description 무액면주식 변경 — 액면가 / 개별주당자본금 입력을 바꿔 보이고 개별주당자본금을 0 으로 둔다 (원본 cmb_NPARVALSTK_YN OnSelChange — §6.2)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.cmb_NPARVALSTK_YN_onviewchange = function (info) {
    try {
        const isNparval = (cmb_NPARVALSTK_YN.getValue() === "Y");
        if (isNparval) {
            edt_PARVAL.hide();
            edt_PER1STK_CAP.show("");
        } else {
            edt_PARVAL.show("");
            edt_PER1STK_CAP.hide();
        }
        edt_PER1STK_CAP.setValue("0");      // 원본은 두 가지 모두 개별주당자본금을 0 으로 둔다
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05113.cmb_NPARVALSTK_YN_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.chk_INDEFINPD_YN_oncheckboxclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 무기한여부 클릭 — 존속기한(년·월·일)과 만료일을 비운다 (원본 chk_INDEFINPD_YN onclick — §4)
 * @param {Number} index 클릭한 항목 순번
 * @param {Boolean} checked 체크 여부
 * @returns
 * @hidden N
 */
scwin.chk_INDEFINPD_YN_oncheckboxclick = function (index, checked) {
    try {
        edt_PREFSTK_CONTIN_DEADLINE_YYS.setValue("");
        edt_PREFSTK_CONTIN_DEADLINE_MM.setValue("");
        edt_PREFSTK_CONTIN_DEADLINE_DYS.setValue("");
        edt_PREFSTK_END_DD.setValue("");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05113.chk_INDEFINPD_YN_oncheckboxclick" });
    }
};

