///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectCode
 * @author Inswave
 * @date 2026. 10. 29
 * @description 공통 코드(통화ISO코드 CURR_ISO_CD · 주식발행사유 STK_ISU_RSN_CD)를 한 번에 받는다. (원본 fn_searchCode · fn_SetComboCode — §5.1, 공통 계약서 §4.5)
 * @returns
 * @hidden N
 */
scwin.selectCode = async function () {
    const sbmOptions = {
        id : "sbm_listCodeValue",
        action : "/api/listing/common/code/list-code-value",
        method : "get",
        ref : "dma_codReq",
        target : "dlt_currIsoCd=body.CURR_ISO_CD, dlt_stkIsuRsnCd=body.STK_ISU_RSN_CD",
        isProcessMsg : false
    };

    dma_codReq.set("codeList", "CURR_ISO_CD, STK_ISU_RSN_CD");
    await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 상세 조회 → 무액면 표시 → 버튼 상태. (원본 fn_read_sync + dts_Isu OnLoadCompleted — §5.2)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectDetail = async function () {
    const sbmOptions = {
        id : "sbm_select",
        action : "/api/listing/lstproc/kind/listing-review/new-list-isu/select-one",
        method : "get",
        ref : "dma_isuReq",
        target : "dma_isuRes=body",
        isProcessMsg : false
    };

    dma_isuReq.set("bzProcsNo", scwin.bzProcsNo);
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;

    scwin.applyNparval(dma_isuRes.get("nparvalstkYn"));
    scwin.applyButtonState();
    return true;
};

/**
 * @method
 * @name scwin.selectNewPrefstk
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신형우선주 이력 — 있으면 존속기한·만료일·무기한여부·비고를 상세에 채우고, 없으면 비운다.
 * 원본은 이력 조회 없이 없는 데이터셋(dts_NEWPREFSTK)을 읽었다 — 같은 업무 ULDSTF05105 에 적용된 API 를 쓴다. (원본 fn_nprefstk_read_sync — §5.3, §10 #3)
 * @param {String} isuCd 종목코드
 * @returns
 * @hidden N
 */
scwin.selectNewPrefstk = async function (isuCd) {
    const sbmOptions = {
        id : "sbm_selectNewPrefstk",
        action : "/api/listing/lstproc/stock/issuance-manage-new-prestk/select-one",
        method : "get",
        ref : "dma_newprefstkReq",
        target : "dma_newprefstkRes=body",
        isProcessMsg : false
    };

    dma_newprefstkReq.set("isuCd", isuCd);
    dma_newprefstkRes.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    // 원본 dts_NEWPREFSTK.getTotalRow() > 0 — 응답에 종목코드가 있으면 이력이 있는 것으로 본다
    const hasHist = !$c.util.isEmpty(dma_newprefstkRes.get("isuCd"));
    dma_isuRes.set("prefstkIsuDd", hasHist ? dma_newprefstkRes.get("isuDd") : "");
    dma_isuRes.set("prefstkDivRt", hasHist ? dma_newprefstkRes.get("prefstkDivRt") : "");
    dma_isuRes.set("prefstkContinDeadlineYys", hasHist ? dma_newprefstkRes.get("prefstkContinDeadlineYys") : "");
    dma_isuRes.set("prefstkContinDeadlineMm", hasHist ? dma_newprefstkRes.get("prefstkContinDeadlineMm") : "");
    dma_isuRes.set("prefstkContinDeadlineDys", hasHist ? dma_newprefstkRes.get("prefstkContinDeadlineDys") : "");
    dma_isuRes.set("prefstkEndDd", hasHist ? dma_newprefstkRes.get("prefstkEndDd") : "");
    dma_isuRes.set("indefinpdYn", hasHist ? dma_newprefstkRes.get("indefinpdYn") : "");
    dma_isuRes.set("newprefstkRemk", hasHist ? dma_newprefstkRes.get("newprefstkRemk") : "");
};

/**
 * @method
 * @name scwin.selectNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 업무처리번호 채번 (원본 fn_save 의 $c.stf.fn_getNewBzProcNo — §5.4)
 * @returns {Promise<String>} 업무처리번호(받지 못하면 "")
 * @hidden N
 */
scwin.selectNewBzProcsNo = async function () {
    const sbmOptions = {
        id : "sbm_newBzprocsno",
        action : "/api/listing/lstproc/ksqexpeval/new-bzprocsno",
        method : "get",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return "";    // 진행 중 처리가 있어 이번 호출은 건너뜀

    // TODO: 채번 응답 모양 확인 — body 가 문자열인지 { bzProcsNo } 인지 (§10 #4)
    return scwin.getBzProcsNoOf(result.responseJSON?.body ?? result.responseJSON);
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 29
 * @description 등록(I)·수정(U)·삭제(D) 전송. 성공하면 isSaved 를 세우고, 삭제는 팝업을 닫고, 등록·수정은 다시 조회한다.
 * (원본 fn_trs + trs_Save OnSuccess/OnFail — §5.5)
 * @param {String} trJob 처리구분 I: 저장, U: 수정, D: 삭제
 * @param {String} bzProcsNo 업무처리번호 — 신규는 방금 채번한 번호
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (trJob, bzProcsNo) {
    const jobNm = scwin.JOB_NM[trJob];

    const sbmOptions = {
        id : "sbm_save",
        action : (trJob === "I") ? "/api/listing/lstproc/kind/listing-review/stock/list-isu/register"
               : (trJob === "U") ? "/api/listing/lstproc/kind/listing-review/stock/list-isu/modify"
               : "/api/listing/lstproc/kind/listing-review/stock/list-isu/remove",
        method : "post",
        ref : "dma_saveReq",
        mediatype : "application/json",
        isProcessMsg : false
    };

    // 종목 상세 — 원본 fn_trs 가 덧붙이던 값을 더한다
    const isuinfo = {
        ...dma_isuRes.getJSON(),
        bzProcsNo : bzProcsNo,
        isurCd : txb_ISUR_CD.getValue(),
        spotIsuTrdMktTpCd : scwin.mktTpCd,
        listBzTpCd : $c.lc.getGlbValue("LIST_BZ_TP_CD_100"),           // 신규상장
        listProcsStatCd : scwin.LIST_PROCS_STAT_CD[trJob]
    };
    dma_saveReq.set("bzProcsNo", bzProcsNo);
    dma_saveReq.set("isuinfo", isuinfo);

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
        scwin.applyButtonState();
        return;
    }

    scwin.isSaved = true;
    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));

    if (trJob === "D") {
        // 부모는 isSaved 를 보고 목록을 다시 조회하고 행 포커스를 되돌린다 (공통 계약서 §2)
        await $c.win.closePopup({ isSaved : true });
        return;
    }

    // 등록이면 이 건의 번호로 확정 — 응답에 번호가 오면 그 값을 쓴다 (§10 #4)
    if (trJob === "I") {
        scwin.bzProcsNo = scwin.getBzProcsNoOf(result.responseJSON?.body) || bzProcsNo;
    }
    await scwin.selectDetail();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 준비 — 빈 상세, 회사, 신규 버튼 상태, 상장일·상장방식, 유가 영문심볼 기본값.
 * 회사 업무처리번호가 없거나 상장일이 오늘 이전이면 처리 버튼을 잠근다. (원본 init 의 신규 분기 — §3)
 * @param {Object} param 부모가 넘긴 data
 * @returns
 * @hidden N
 */
scwin.initNewForm = async function (param) {
    dma_isuRes.setEmptyValue();
    txb_ISUR_CD.setValue(String(param.isurCd ?? ""));
    scwin.initNparval();
    scwin.applyButtonState();

    if (scwin.coBzProcsNo === "") {
        await $c.win.alert("먼저 회사정보를 입력후 종목정보를 입력바랍니다.");
        $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
    } else {
        edt_LIST_DD.setValue(String(param.listDd ?? ""));
        cmb_LIST_METHD_TP_CD.setValue($c.lc.getGlbValue("LIST_METHD_TP_CD_4"));     // 신규상장
    }

    // 상장일이 오늘 이전이면 잠근다 (원본: 비어 있어도 "" <= 오늘 이라 잠긴다)
    if (edt_LIST_DD.getValue() <= $c.date.getServerDateTime("yyyyMMdd")) {
        $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
    }

    if (scwin.mktTpCd === "1") {
        panel_ISU_ENG_SYMBL.show("");
        txb_ISU_ENG_SYMBL.setValue(String(param.isurSymbl ?? ""));     // 유가는 회사 영문심볼을 기본값으로
    } else if (scwin.mktTpCd === "2") {
        panel_ISU_ENG_SYMBL.hide();
    }
};

/**
 * @method
 * @name scwin.applyButtonState
 * @author Inswave
 * @date 2026. 10. 29
 * @description 모드별 버튼 — 신규면 저장만(종목 찾기 가능), 수정이면 상장일이 오늘 이후일 때만 수정·삭제(종목 찾기 잠금). (원본 dts_Isu OnLoadCompleted · fn_initForm — §6.1)
 * @returns
 * @hidden N
 */
scwin.applyButtonState = function () {
    if (scwin.bzProcsNo === "") {
        img_ISU_CD.setDisabled(false);
        $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);
        return;
    }

    img_ISU_CD.setDisabled(true);
    const today = $c.date.getServerDateTime("yyyyMMdd");
    $c.util.setButtonState("grp_btnBox", (edt_LIST_DD.getValue() > today) ? "update" : "error", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.initNparval
 * @author Inswave
 * @date 2026. 10. 29
 * @description 무액면주식 기본값(아니요) — 액면가를 보이고 개별주당자본금은 숨기고 0 으로 둔다. (원본 fn_SetComboCode 앞부분 — §6.2)
 * @returns
 * @hidden N
 */
scwin.initNparval = function () {
    cmb_NPARVALSTK_YN.setValue("N");
    edt_PARVAL.show("");
    edt_PER1STK_CAP.hide();
    edt_PER1STK_CAP.setValue("0");
};

/**
 * @method
 * @name scwin.applyNparval
 * @author Inswave
 * @date 2026. 10. 29
 * @description 조회한 무액면 여부에 따라 액면가 / 개별주당자본금 중 하나를 보이고, 숨긴 쪽은 0 으로 둔다. (원본 fn_read_sync — §6.2)
 * @param {String} nparvalstkYn 무액면여부 Y / N
 * @returns
 * @hidden N
 */
scwin.applyNparval = function (nparvalstkYn) {
    if (nparvalstkYn === "Y") {
        edt_PARVAL.hide();
        edt_PER1STK_CAP.show("");
        edt_PARVAL.setValue("0");
    } else {
        edt_PARVAL.show("");
        edt_PER1STK_CAP.hide();
        edt_PER1STK_CAP.setValue("0");
    }
};

/**
 * @method
 * @name scwin.isNparval
 * @author Inswave
 * @date 2026. 10. 29
 * @description 무액면주식인가 — 원본은 값이 N 이거나 비었을 때만 자본금을 계산했다. (§6.3)
 * @returns {Boolean} 무액면(Y)이면 true
 * @hidden N
 */
scwin.isNparval = function () {
    const val = cmb_NPARVALSTK_YN.getValue();
    return !(val === "N" || val === "");
};

/**
 * @method
 * @name scwin.setInitLabel
 * @author Inswave
 * @date 2026. 10. 29
 * @description 증권그룹이 DR 이면 주식수 라벨을 DR 로 바꾸고 액면가·자본금 영역을 숨긴다. (원본 fn_setInitLabel — §6.1)
 * 원본의 소수 자릿수(MaxDecimalPlace) 지정은 옮기지 않는다(§8 #9, §10 #6).
 * @returns
 * @hidden N
 */
scwin.setInitLabel = function () {
    if (scwin.secugrpId === $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        scwin.isuShrsLabelNm = "DR";
        lb_PARVAL.setValue("DR당액면가");
        lb_BF_ACC_ISU_SHRS.setValue("변경전 상장DR수");
        lb_ISU_SHRS.setValue("증감상장DR수");
        lb_ACC_ISU_SHRS.setValue("변경후 상장DR수");
        panel_PARVAL.hide();
        panel_ISU_CAP.hide();
    } else {
        scwin.isuShrsLabelNm = "주식";
        panel_PARVAL.show("");
        panel_ISU_CAP.show("");
    }
};

/**
 * @method
 * @name scwin.setSymblComponent
 * @author Inswave
 * @date 2026. 10. 29
 * @description 유가(1)만 영문종목심볼을 입력하고 [중복체크]를 보인다. (원본 fn_setSumblComponent — §6.1)
 * @returns
 * @hidden N
 */
scwin.setSymblComponent = function () {
    if (scwin.mktTpCd === "1") {
        txb_ISU_ENG_SYMBL.setReadOnly(false);
        img_ISU_ENG_SYMBL.show("");
    } else {
        txb_ISU_ENG_SYMBL.setReadOnly(true);
        img_ISU_ENG_SYMBL.hide();
    }
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 발행기관의 미상장종목 찾기(ULDSTF92016) → 종목 정보·주식의종류 채움 → 신형우선주 이력·변경전 상장주식수/자본금 조회.
 * 원본은 인자 없이 열고 결과를 버렸다(§8 #5). (원본 img_ISU_CD onclick + fn_SetParIsuCd — §6.5)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    const res = await $c.lc.popFindNewIsuOfIsur(scwin.secugrpId, txb_ISUR_CD.getValue());
    if (res?.isCloseButtonClick === true || $c.util.isEmpty(res?.isuCd)) return;

    // 원본 fn_SetParIsuCd 가 채우던 항목만 채운다(발행회차·발행일은 채우지 않음)
    txb_ISU_CD.setValue(res.isuCd);
    txb_ISU_KOR_NM.setValue(res.isuNm);
    txb_ISU_KOR_ABBRV.setValue(res.isuSnm);         // 종목약어명
    txb_ISU_ENG_NM.setValue(res.isuEngNm);          // 영문종목명
    txb_ISU_ENG_ABBRV.setValue(res.isuEngSnm);      // 영문약어명
    txb_ISU_SRT_CD.setValue(res.isuSrtCd);
    txb_ISU_ENG_SYMBL.setValue(res.isuEngSymbl);
    cmb_CURR_ISO_CD.setValue(res.currIsoCd);

    // 주식의종류 — DR 은 KDR, 외국주권은 보통주(000), 그 밖은 종목코드 9~11번째 자리
    if (scwin.secugrpId === $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        cmb_STKCERT_KIND_CD.setValue("KDR");
    } else if (scwin.secugrpId === $c.lc.getGlbValue("SECUGRP_ID_FS")) {
        cmb_STKCERT_KIND_CD.setValue(scwin.STKCERT_KIND_CD_COMMON);
    } else {
        cmb_STKCERT_KIND_CD.setValue(String(res.isuCd).substring(8, 11));
    }

    await scwin.selectNewPrefstk(res.isuCd);
    // 변경전 상장주식수·자본금 — 원본 $c.lic.fn_bf_read_sync1 (공통 계약서 §4.1)
    await $c.lc.bfReadSync(txb_ISU_CD, edt_LIST_DD, edt_BF_ACC_ISU_SHRS, edt_BF_ACC_ISU_CAP);
};

/**
 * @method
 * @name scwin.checkSymbl
 * @author Inswave
 * @date 2026. 10. 29
 * @description 영문종목심볼 중복 확인 — 결과 문구를 안내한다. (원본 img_ISU_ENG_SYMBL onclick — §6.4)
 * @returns
 * @hidden N
 */
scwin.checkSymbl = async function () {
    if (txb_ISU_ENG_SYMBL.getValue() === "") {
        await $c.win.alert("[영문종목심볼]을 입력하세요.");
        txb_ISU_ENG_SYMBL.focus();
        return;
    }

    // pcc 는 async — 원본은 await 없이 불렀고 문구는 없는 전역(MSG_SYMBL_DOUBLE_INPUT)·$c.ut 를 읽었다(§8 #6)
    await $c.lc.chkIsuSymblDoubleInput(txb_ISU_ENG_SYMBL.getValue(), txb_ISU_CD.getValue());
    const msg = $c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT");
    if (!$c.util.isEmpty(msg)) {
        await $c.win.alert(msg);
    }
};

/**
 * @method
 * @name scwin.calcAccIsuShrs
 * @author Inswave
 * @date 2026. 10. 29
 * @description 변경후 상장주식수 = 변경전 상장주식수 + 증감주식수 (원본 calcuAccIsuShrs — §6.3)
 * @returns
 * @hidden N
 */
scwin.calcAccIsuShrs = function () {
    const bfShrs = Number.parseInt(edt_BF_ACC_ISU_SHRS.getValue() || 0, 10);
    const isuShrs = Number.parseInt(edt_ISU_SHRS.getValue() || 0, 10);
    edt_ACC_ISU_SHRS.setValue(bfShrs + isuShrs);
};

/**
 * @method
 * @name scwin.isNoCapRsn
 * @author Inswave
 * @date 2026. 10. 29
 * @description 자본금이 늘지 않는 주식발행사유(이익소각·상호변경·액면병합·액면분할)인가 (원본 calcusuCap · calcuAccIsuCap 의 사유 분기 — §6.3)
 * @returns {Boolean} 해당하면 true
 * @hidden N
 */
scwin.isNoCapRsn = function () {
    return scwin.NO_CAP_RSN_CD.includes(cmb_STK_ISU_RSN_CD.getValue());
};

/**
 * @method
 * @name scwin.calcIsuCap
 * @author Inswave
 * @date 2026. 10. 29
 * @description 증감 상장자본금 — DR 은 비우고, 자본금이 늘지 않는 사유는 0,
 * 투자회사(MF)·사회간접자본투융자회사(IF)는 발행가 × 증감주식수, 그 밖은 액면가 × 증감주식수. (원본 calcusuCap — §6.3)
 * @returns
 * @hidden N
 */
scwin.calcIsuCap = function () {
    if (scwin.secugrpId === $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        edt_ISU_CAP.setValue("");
        return;
    }

    let isuCap = 0;
    if (!scwin.isNoCapRsn()) {
        const isMfIf = (scwin.secugrpId === $c.lc.getGlbValue("SECUGRP_ID_MF") || scwin.secugrpId === $c.lc.getGlbValue("SECUGRP_ID_IF"));
        const unitPrc = Number.parseFloat((isMfIf ? edt_ISU_PRC.getValue() : edt_PARVAL.getValue()) || 0);
        isuCap = unitPrc * Number.parseFloat(edt_ISU_SHRS.getValue() || 0);
    }
    edt_ISU_CAP.setValue(isuCap);
};

/**
 * @method
 * @name scwin.calcAccIsuCap
 * @author Inswave
 * @date 2026. 10. 29
 * @description 변경후 상장자본금 — DR 은 비우고, 자본금이 늘지 않는 사유는 변경전 상장자본금 그대로(증감 0),
 * 그 밖은 증감 상장자본금을 다시 계산해 변경전 + 증감. (원본 calcuAccIsuCap — §6.3)
 * @returns
 * @hidden N
 */
scwin.calcAccIsuCap = function () {
    if (scwin.secugrpId === $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        edt_ACC_ISU_CAP.setValue("");
        return;
    }

    if (scwin.isNoCapRsn()) {
        edt_ISU_CAP.setValue(0);
        edt_ACC_ISU_CAP.setValue(edt_BF_ACC_ISU_CAP.getValue());
        return;
    }

    scwin.calcIsuCap();
    const accCap = Number.parseFloat(edt_BF_ACC_ISU_CAP.getValue() || 0) + Number.parseFloat(edt_ISU_CAP.getValue() || 0);
    edt_ACC_ISU_CAP.setValue(accCap);
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장·수정 전 입력 검증. 원본 fn_CheckForm 의 순서·문구를 그대로 둔다(보통주 약명 일치 포함). (§6.10)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    const today = $c.date.getServerDateTime("yyyyMMdd");
    const label = scwin.isuShrsLabelNm;

    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[법인코드] 항목값이  없습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (cmb_LIST_METHD_TP_CD.getValue() === "") {
        await $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if (txb_ISU_SRT_CD.getValue() === "") {
        // 원본도 안내만 하고 진행한다(§8 #8)
        await $c.win.alert("[종목단축코드]항목값이  없습니다.");
    }
    if (txb_ISU_KOR_NM.getValue() === "") {
        await $c.win.alert("[한글종목명]을 입력하세요.");
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_KOR_NM, 60, "한글종목명")) return false;
    if (txb_ISU_KOR_ABBRV.getValue() === "") {
        await $c.win.alert("[한글종목약명]을 입력하세요.");
        txb_ISU_KOR_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_KOR_ABBRV, 30, "한글종목약명")) return false;
    if (txb_ISU_ENG_NM.getValue() === "") {
        await $c.win.alert("[영문종목명]을 입력하세요.");
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 60, "영문종목명")) return false;
    if (txb_ISU_ENG_ABBRV.getValue() === "") {
        await $c.win.alert("[영문종목약명]을 입력하세요.");
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 30, "영문종목약명")) return false;
    if (scwin.mktTpCd === "1") {
        if (txb_ISU_ENG_SYMBL.getValue() === "") {
            await $c.win.alert("[영문종목심볼]을 입력하세요.");
            txb_ISU_ENG_SYMBL.focus();
            return false;
        }
        // TODO: pcc chkSymblDoubleInput 이 미사용 심볼도 중복으로 판정하는지 확인 (§10 #1)
        if (!await $c.lc.chkIsuSymblDoubleInput(txb_ISU_ENG_SYMBL.getValue(), txb_ISU_CD.getValue())) {
            await $c.win.alert($c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT"));
            return false;
        }
    }
    if (edt_LIST_DD.getValue() === "") {
        await $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (today >= edt_LIST_DD.getValue()) {
        await $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (edt_ISU_DD.getValue() === "") {
        await $c.win.alert("[발행일]을 입력하세요.");
        edt_ISU_DD.focus();
        return false;
    }
    if (edt_ISU_RND.getValue() === "") {
        await $c.win.alert("[발행회차]를 입력하세요.");
        edt_ISU_RND.focus();
        return false;
    }
    if (cmb_STKCERT_KIND_CD.getValue() === "") {
        await $c.win.alert("[주식의종류]를 선택하세요.");
        cmb_STKCERT_KIND_CD.focus();
        return false;
    }
    if (cmb_STK_ISU_RSN_CD.getValue() === "") {
        await $c.win.alert("[주식발행사유]를 선택하세요.");
        cmb_STK_ISU_RSN_CD.focus();
        return false;
    }
    // 투자회사(MF)·사회간접자본투융자회사(IF)·DR 이 아니면 액면가 필수
    const noParvalGrp = [$c.lc.getGlbValue("SECUGRP_ID_MF"), $c.lc.getGlbValue("SECUGRP_ID_IF"), $c.lc.getGlbValue("SECUGRP_ID_DR")];
    if (!noParvalGrp.includes(scwin.secugrpId) && String(edt_PARVAL.getValue()) === "") {
        await $c.win.alert("[액면가]을 입력하세요.");
        edt_PARVAL.focus();
        return false;
    }
    if (String(edt_ISU_PRC.getValue()) === "") {
        await $c.win.alert("[발행가]을 입력하세요.");
        edt_ISU_PRC.focus();
        return false;
    }
    if (String(edt_ISU_SHRS.getValue()) === "") {
        await $c.win.alert("[증감" + label + "수]을 입력하세요.");
        edt_ISU_SHRS.focus();
        return false;
    }
    if (scwin.secugrpId !== $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        if (String(edt_ISU_CAP.getValue()) === "") {
            await $c.win.alert("[증감 상장자본금]을 입력하세요.");
            edt_ISU_CAP.focus();
            return false;
        }
        if (String(edt_ACC_ISU_SHRS.getValue()) === "") {
            await $c.win.alert("[변경후 상장" + label + "수]을 입력하세요.");
            edt_ACC_ISU_SHRS.focus();
            return false;
        }
        if (String(edt_ACC_ISU_SHRS.getValue()) === "0") {
            await $c.win.alert("[변경후 상장" + label + "수]값이 '0' 입니다. \n[증감 상장" + label + "수]가 올바르게 입력되었는지 확인바랍니다.");
            edt_ACC_ISU_SHRS.focus();
            return false;
        }
        if (String(edt_ACC_ISU_CAP.getValue()) === "") {
            await $c.win.alert("[변경후 상장자본금]을 입력하세요.");
            edt_ACC_ISU_CAP.focus();
            return false;
        }
        if (String(edt_ACC_ISU_CAP.getValue()) === "0") {
            await $c.win.alert("[변경후 상장자본금]값이 '0' 입니다. '\n[증감 상장자본금]이 올바르게 입력되었는지 확인바랍니다.");
            edt_ACC_ISU_CAP.focus();
            return false;
        }
    }
    if (edt_DIV_RECK_DD1.getValue() === "") {
        await $c.win.alert("[배당기산일1]을 입력하세요.");
        edt_DIV_RECK_DD1.focus();
        return false;
    }
    // 보통주는 한글종목약명이 회사 한글약명과 같아야 한다 (YSH, 2012/02/02) — 원본은 부모의 없는 id(txb_COM_ABBRV)를 읽었다(§8 #4)
    if (cmb_STKCERT_KIND_CD.getValue() === scwin.STKCERT_KIND_CD_COMMON && txb_ISU_KOR_ABBRV.getValue() !== scwin.comAbbrv) {
        await $c.win.alert("보통주일경우 한글회사약명 과 종목약명이 동일해야 합니다. 확인하시기 바랍니다.");
        txb_ISU_KOR_ABBRV.focus();
        return false;
    }
    // 무액면주식 — 개별주당자본금은 발행가의 50% 이상 ~ 발행가 이하
    if (cmb_NPARVALSTK_YN.getValue() === "Y") {
        const per1stkCap = Number.parseFloat(edt_PER1STK_CAP.getValue());
        const isuPrc = Number.parseFloat(edt_ISU_PRC.getValue());
        if (per1stkCap > isuPrc) {
            await $c.win.alert("개별주당자본금은  발행가 이하로 입력해 주십시오.");
            edt_PER1STK_CAP.focus();
            return false;
        }
        if (per1stkCap < (isuPrc * 0.5)) {
            await $c.win.alert("개별주당자본금은 발행가의 50% 이상으로 입력해 주십시오");
            edt_PER1STK_CAP.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name scwin.getBzProcsNoOf
 * @author Inswave
 * @date 2026. 10. 29
 * @description 응답 body 에서 업무처리번호를 꺼낸다 — 문자열이면 그대로, 객체면 bzProcsNo. (§10 #4)
 * @param {*} body 응답 body
 * @returns {String} 업무처리번호(없으면 "")
 * @hidden N
 */
scwin.getBzProcsNoOf = function (body) {
    if (body === null || body === undefined) return "";
    if (typeof body === "object") return String(body.bzProcsNo ?? "");
    return String(body);
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 저장 — 검증 → 확인 → 채번(14자리) → 등록. 채번이 확인보다 뒤라 취소한 건에는 번호가 소비되지 않는다. (원본 fn_save — §6.7)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";
    if (!await scwin.validate()) return;
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const bzProcsNo = await scwin.selectNewBzProcsNo();
    if (bzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    dma_isuRes.set("bzProcsNo", bzProcsNo);
    await scwin.saveTrs("I", bzProcsNo);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정 — 검증 → 확인 → 수정 전송. (원본 fn_update — §6.8)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";
    if (!await scwin.validate()) return;
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs("U", scwin.bzProcsNo);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 29
 * @description 삭제 — 확인 → 버튼 잠금 → 삭제 전송(성공하면 팝업을 닫는다). (원본 fn_delete — §6.9)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    // 원본 "delete" 는 공통에 없는 상태라 동작하지 않았다(§8 #3)
    $c.util.setButtonState("grp_btnBox", "disabled", scwin.BTN_MAP);
    await scwin.saveTrs("D", scwin.bzProcsNo);
};

/**
 * @method
 * @name scwin.openKindStkDetail
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종류주식상세(ULDSTF05106). 반환은 없고 닫힐 때까지 기다린다. 원본처럼 저장 전에도 연다. (원본 btn_KIND_STK_DTL onclick — §6.6, 공통 계약서 §2 05106)
 * @returns
 * @hidden N
 */
scwin.openKindStkDetail = async function () {
    const data = {
        bzProcsNo : scwin.bzProcsNo,
        listProcsStatCd : dma_isuRes.get("listProcsStatCd"),    // 원본은 넘기지 않았다(05106 은 부모 전역 vListProcsStatCd 를 읽었다)
        prelmInvstgBzProcsNo : scwin.prelmInvstgBzProcsNo,
        mktTpCd : scwin.mktTpCd
    };
    const opts = {
        id : "ULDSTF05106",
        popupName : $c.lc.getSecuGrpNm(scwin.secugrpId) + " 종류주식상세",
        width : 1135,
        height : 840,
        frameModal : "top"
    };

    await $c.win.openPopup("/ui/lst/kindstk/ULDSTF05106.xml", opts, data);
};
